const kv=new Map(), ses=new Map(); let bk=[], fl=[], bseq=0;
class Pool{ async end(){} async query(sql,p=[]){
 sql=sql.trim();
 if(/^delete from kv/.test(sql)){kv.clear();return {rows:[]};}
 if(sql==='delete from sessions'){ses.clear();return {rows:[]};}
 if(/^select 1/.test(sql)||/^create table/.test(sql)||/^alter table/.test(sql)) return {rows:[]};
 if(/^select value, rev from kv where key=/.test(sql)){const r=kv.get(p[0]);return {rows:r?[{value:JSON.parse(JSON.stringify(r.value)),rev:r.rev}]:[]};}
 if(/^insert into kv.*where \(kv\.value->>'until'\)/.test(sql)){const o=kv.get(p[0]);if(o&&Number(o.value.until)>=p[2])return {rows:[]};const rev=o?o.rev+1:1;kv.set(p[0],{value:JSON.parse(p[1]),rev});return {rows:[{rev}]};}
 if(/^update kv set value=\$2 where key=\$1/.test(sql)){const o=kv.get(p[0]);if(o)o.value=JSON.parse(p[1]);return {rows:[]};}
 if(/^insert into kv/.test(sql)){const o=kv.get(p[0]);const rev=o?o.rev+1:1;kv.set(p[0],{value:JSON.parse(p[1]),rev});return {rows:[{rev}]};}
 if(/^select key, value from kv/.test(sql)){return {rows:[...kv.entries()].filter(([k])=>/^(nx_accounting_v1|nexora_cal_reminders|nexora_stat_)/.test(k)).map(([key,v])=>({key,value:v.value}))};}
 if(/^select role, uid, exp, ph from sessions/.test(sql)){const s=ses.get(p[0]);return {rows:s?[s]:[]};}
 if(/^delete from sessions where token/.test(sql)){ses.delete(p[0]);return {rows:[]};}
 if(/^delete from sessions where exp/.test(sql)){return {rows:[]};}
 if(/^delete from sessions where role=\$1 and lower\(uid\)=\$2/.test(sql)){for(const [t,s] of [...ses]) if(s.role===p[0]&&String(s.uid).toLowerCase()===p[1]&&(p[2]===undefined||t!==p[2])) ses.delete(t);return {rows:[]};}
 if(/^insert into sessions/.test(sql)){ses.set(p[0],{role:p[1],uid:p[2],exp:p[3],ph:p[4]});return {rows:[]};}
 if(/^update sessions set ph=\$1 where role=\$2 and uid=\$3/.test(sql)){for(const s of ses.values()) if(s.role===p[1]&&s.uid===p[2]) s.ph=p[0];return {rows:[]};}
 if(/^update sessions set ph=\$1 where token=\$2/.test(sql)){const s=ses.get(p[1]); if(s) s.ph=p[0];return {rows:[]};}
 if(/^insert into backups/.test(sql)){const id=++bseq;bk.push({id,kind:p[0],data:JSON.parse(p[1]),created_at:new Date().toISOString()});return {rows:[{id,created_at:bk[bk.length-1].created_at}]};}
 if(/^delete from backups where kind/.test(sql)){const keep=bk.filter(b=>b.kind===p[0]).sort((a,b)=>b.id-a.id).slice(0,p[1]).map(b=>b.id);bk=bk.filter(b=>b.kind!==p[0]||keep.includes(b.id));return {rows:[]};}
 if(/^select created_at from backups where kind/.test(sql)){const l=bk.filter(b=>b.kind===p[0]).sort((a,b)=>b.id-a.id)[0];return {rows:l?[{created_at:l.created_at}]:[]};}
 if(/^select id, created_at, kind, octet_length/.test(sql)){return {rows:bk.slice().sort((a,b)=>b.id-a.id).map(b=>({id:b.id,created_at:b.created_at,kind:b.kind,size:JSON.stringify(b.data).length}))};}
 if(/^select kind, created_at, data from backups/.test(sql)){const b=bk.find(x=>x.id==p[0]);return {rows:b?[b]:[]};}
 if(/^select data from backups/.test(sql)){const b=bk.find(x=>x.id==p[0]);return {rows:b?[{data:b.data}]:[]};}
 if(/^insert into files/.test(sql)){fl.push({id:p[0],owner:p[1],name:p[2],mime:p[3],size:p[4],data:p[5],created_at:new Date().toISOString(),uploaded_by:p[6]});return {rows:[]};}
 if(/^select id, owner, name, mime, size, created_at, uploaded_by from files/.test(sql)){return {rows:fl.slice().reverse()};}
 if(/^select coalesce\(sum\(size\),0\)/.test(sql)){return {rows:[{total:fl.reduce((a,f)=>a+f.size,0)}]};}
 if(/^select id, owner, name, mime, data from files/.test(sql)){const f=fl.find(x=>x.id===p[0]);return {rows:f?[f]:[]};}
 if(/^delete from files where id/.test(sql)){fl=fl.filter(x=>x.id!==p[0]);return {rows:[]};}
 throw new Error('SQL? '+sql);
}}
module.exports={Pool};
